-- No cambia existencias: stock inicial = 0; registrar compras en Almacén.
alter table public.products add column if not exists category text not null default 'otros';
create index if not exists idx_products_category on public.products(category);
-- La importación es repetible: evita duplicar productos por nombre.
create unique index if not exists idx_products_name_unique on public.products(lower(name));
